    "Lo que tardan en desplazarse los ejércitos por el mapa. Lenta da la sensación de mover huestes enormes por distancias largas.": "How long armies take to move across the map. Slow gives the feeling of moving huge hosts over long distances.",
    "Al terminar cada estación, ver a velocidad acelerada las marchas, batallas, asedios y conquistas de todas las potencias.": "At the end of each season, watch at accelerated speed the marches, battles, sieges and conquests of every power.",
