    "Tu reino": "Your realm",
    "Gobiernas {}. Tus provincias llevan tu color. Toca cualquier provincia del mapa para ver sus tropas, ánimo y edificios en el panel.": "You rule {}. Your provinces bear your color. Tap any province on the map to see its troops, mood and buildings in the panel.",
    "Recluta": "Recruit",
    "En la pestaña Provincia, sección «Reclutar», compra levas con oro en una de tus ciudades. Pasa el ratón sobre cada clase para ver sus fuerzas y debilidades.": "In the Province tab, “Recruit” section, buy levies with gold in one of your cities. Hover over each class to see its strengths and weaknesses.",
    "Sal a campaña": "Take the field",
    "En la sección «Ejército» forma un ejército: aparecerá un estandarte en el mapa. Tócalo y luego una casilla iluminada para marchar.": "In the “Army” section, form an army: a banner will appear on the map. Tap it and then a lit tile to march.",
    "Gobierna": "Govern",
    "Las pestañas de arriba llevan a la Corte, la Diplomacia, el Tesoro y el Progreso. No hace falta tocarlo todo: empieza por lo que te llame.": "The tabs above lead to the Court, Diplomacy, the Treasury and Progress. You need not touch everything: start with what draws you.",
    "Pasa la estación": "End the season",
    "Cuando termines, pulsa «{}» (tecla E). Las demás potencias moverán y llegará la estación siguiente.": "When you are done, press “{}” (key E). The other powers will move and the next season will come.",
