    "Defiendes la plaza: coloca tus unidades dentro de la muralla (la zona clara). Arqueros junto al lienzo, la línea detrás y la caballería al fondo, lista para salir por una puerta.": "You defend the stronghold: place your units inside the walls (the light area). Archers by the wall, the line behind them and the cavalry at the back, ready to sally from a gate.",
