    "Arrastra tus unidades dentro de la franja clara. Lanceros al frente frenan la caballería; arqueros detrás; caballería en las alas. Bosque: cubre y frena jinetes. Colina: mejor tiro y defensa. Río: frena y debilita; usa los vados.": "Drag your units within the light strip. Spearmen in front stop cavalry; archers behind; cavalry on the wings. Forest: gives cover and slows riders. Hill: better shooting and defense. River: slows and weakens; use the fords.",
