    "Las bajas no son instantáneas: el cansancio, las cargas, los flancos y la caída de los vecinos erosionan la moral hasta que una unidad rompe filas. La persecución causa la mayoría de muertos; parte de los heridos vuelve a filas.": "Losses are not instantaneous: fatigue, charges, flanks and the collapse of neighboring units wear down morale until a unit breaks ranks. The pursuit causes most of the deaths; some of the wounded return to the ranks.",
    "Grito de guerra": "War cry",
    "Sobrecoge al enemigo cercano y enardece a los suyos": "Daunts nearby foes and rouses their own",
    "Furia berserker": "Berserker fury",
    "Ataque enorme y sin miedo un rato; después flaquean por debajo de lo normal": "Huge, fearless attack for a while; then they falter below normal",
    "Cierran filas: mucha más defensa y escudo, casi inmóviles": "Close ranks: far more defense and shield, almost immobile",
    "Tortuga de escudos: las flechas apenas hieren; lentos y torpes al golpear": "Shield tortoise: arrows barely wound; slow and clumsy when striking",
    "Carga": "Charge",
    "Embestida a fondo aunque no haya carrerilla": "All-out onslaught even without a run-up",
    "Lluvia de flechas": "Rain of arrows",
    "Descargas cerradas que oscurecen el cielo": "Dense volleys that darken the sky",
    "Golpe por sorpresa (mejor desde el bosque)": "Surprise strike (best from the forest)",
    "Fuego que ni la armadura ni el escudo detienen": "Fire that neither armor nor shield can stop",
    "Estampida": "Stampede",
    "Embestida de las bestias: pisotean y aterrorizan": "The beasts charge: they trample and terrify",
    "Espanto": "Terror",
    "Los caballos enemigos cercanos se encabritan: −#% ataque y pierden moral": "Nearby enemy horses rear up: −#% attack and lose morale",
    "Fingen la huida y disparan volviéndose en la silla": "Feign flight and shoot, turning in the saddle",
    "No cederán: la moral no baja del #% un tiempo": "They will not yield: morale stays above #% for a while",
