    "Hacia «Confederación»:": "Toward “Confederation”:",
    "Requiere «Arco huno» adoptada aquí": "Requires “Hunnic bow” adopted here",
    "de haberle robado tierras y honra, y le reta a combate ante testigos.": "of stealing his lands and honor, and challenges him to combat before witnesses.",
    "y le reta a combate ante testigos.": "and challenges him to combat before witnesses.",
    "el ofendido no olvida": "the offended man does not forget",
    "que comparte el mando de las tribus y el reparto del oro.": "who shares the command of the tribes and the division of the gold.",
    "Los chamanes dicen que un arco no puede tener dos cuerdas.": "The shamans say a bow cannot have two strings.",
    "arde de fiebre desde hace nueve días.": "has burned with fever for nine days.",
    "Los médicos de la corte se contradicen": "The court physicians contradict each other",
    "los criados ya hablan en voz baja.": "the servants already speak in whispers.",
    "discute con los clérigos y monta mejor que algunos jinetes.": "argues with the clerics and rides better than some horsemen.",
    "Sus estandartes ardieron, y su nombre quedó solo en las crónicas de los vencedores.": "Its banners burned, and its name survived only in the chronicles of the victors.",
    "Sus estandartes ardieron": "Its banners burned",
