    "{} bajo una regencia": "{} under a regency",
    "Arrianos y nicenos se acusan de herejía en la basílica de {}. Los obispos esperan la palabra del {}; los reinos vecinos escuchan.": "Arians and Nicenes accuse each other of heresy in the basilica of {}. The bishops await the word of the {}; the neighboring realms listen.",
