    "Sucesión disputada": "Disputed succession",
    "Los {} lanzan su grito de guerra; el enemigo se estremece.": "The {} raise their war cry; the enemy trembles.",
    "Los {} muerden el hongo y enloquecen: nada los detiene.": "The {} chew the mushroom and go mad: nothing stops them.",
    "La furia de los {} se apaga: ahora flaquean, exhaustos.": "The fury of the {} fades: now they falter, exhausted.",
    "Los {} cierran el muro de escudos.": "The {} lock the shield wall.",
    "Los {} forman la tortuga: las flechas rebotan en los escudos.": "The {} form the tortoise: arrows glance off their shields.",
    "Los {} cargan con todo.": "The {} charge with everything they have.",
    "Los {} oscurecen el cielo con sus descargas.": "The {} darken the sky with their volleys.",
    "¡Emboscada! Los {} caen por sorpresa sobre el enemigo.": "Ambush! The {} fall upon the enemy by surprise.",
    "Los {} lanzan fuego griego: el enemigo arde.": "The {} hurl Greek fire: the enemy burns.",
    "Los {} embisten en estampida.": "The {} charge in a stampede.",
    "Los {} fingen la huida y disparan volviéndose en la silla.": "The {} feign flight and shoot, turning in the saddle.",
    "Los {} renuevan su juramento: no cederán.": "The {} renew their oath: they will not yield.",
    "Los {} untan sus armas con veneno.": "The {} smear their weapons with poison.",
    "Los {} ofrecen sangre a los dioses: los suyos se enardecen.": "The {} offer blood to the gods: their comrades are roused.",
    "Retumban los tambores de los {}: los suyos recobran el aliento.": "The drums of the {} thunder: their comrades catch their breath.",
